(function() {
    tinymce.PluginManager.add('cleanhtml', function(editor, url) {
        editor.addButton('cleanhtml', {
            title: 'Clean HTML & AI Whitespace',
            icon: 'cleanhtml-custom-icon',
            onPostRender: function() {
                var btn = this;
                var iconEl = btn.$el.find('.mce-ico');
                if (iconEl && iconEl.length) {
                    iconEl.html('<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor" focusable="false" style="display:block;margin:auto;"><path d="M19.36 2.72l1.42 1.42-3.8 3.8-1.42-1.42 3.8-3.8zM5.93 17.57A8 8 0 0 1 12 4.07v2A6 6 0 0 0 7.34 16.16l-1.41 1.41zM2 22l4-4 2.83 2.83L4.83 22H2zm13.17-6.59l4.95-4.95 1.41 1.41-4.95 4.95-1.41-1.41zM9.54 13.96l5.66-5.66 1.41 1.41-5.66 5.66-1.41-1.41z"/></svg>');
                }
            },
            onclick: function() {
                try {
                    var content = editor.getContent();
                    if (!content || !content.trim()) {
                        return;
                    }

                    // 1. Remove Zero-width characters & normalize Unicode whitespace generated by AI (ChatGPT, Claude, Gemini)
                    content = content.replace(/[\u200B\u200C\u200D\uFEFF]/g, '');
                    content = content.replace(/[\u00A0\u2000-\u200A\u202F\u205F\u3000]/g, ' ');
                    content = content.replace(/&nbsp;/gi, ' ');
                    content = content.replace(/&#160;/gi, ' ');

                    // 2. Remove markdown copy-paste fence leftovers (e.g. ```html or ```)
                    content = content.replace(/^```[a-z]*\s*$/gim, '');

                    // 3. Remove consecutive repeated <br> tags (more than 1)
                    content = content.replace(/(?:<br\s*\/?>\s*){2,}/gi, '<br>');

                    // 4. Remove empty paragraphs containing only whitespace, &nbsp;, or <br>
                    content = content.replace(/<p>\s*(?:<br\s*\/?>)?\s*<\/p>/gi, '');
                    content = content.replace(/<(h[1-6]|span|div|strong|em|b|i)\b[^>]*>\s*<\/\1>/gi, '');

                    // 5. Clean leading and trailing whitespace inside common block tags
                    content = content.replace(/(<(?:p|h[1-6]|li|td|th)\b[^>]*>)\s+/gi, '$1');
                    content = content.replace(/\s+(<\/(?:p|h[1-6]|li|td|th)>)/gi, '$1');

                    // 6. Fix spaces before punctuation (common AI copy-paste artifact: "word , text .")
                    content = content.replace(/\s+([\,\.\;\:\!\?])/g, '$1');

                    // 7. Parse DOM to clean attributes, unwrap empty spans & collapse spaces
                    var tempDiv = document.createElement('div');
                    tempDiv.innerHTML = content;

                    var elements = tempDiv.querySelectorAll('*');
                    elements.forEach(function(el) {
                        Array.from(el.attributes).forEach(function(attr) {
                            if (/^(data-(start|end|is-last-node|is-only-node|sourcepos|prompt|chat|message-author-role)|contenteditable)$/i.test(attr.name)) {
                                el.removeAttribute(attr.name);
                            }
                        });

                        if (el.tagName === 'SPAN' && (!el.attributes.length || (el.attributes.length === 1 && el.className === ''))) {
                            if (!el.textContent.trim() && !el.children.length) {
                                el.remove();
                            }
                        }
                    });

                    // Remove empty paragraphs/headings after attribute cleanup
                    tempDiv.querySelectorAll('p, h1, h2, h3, h4, h5, h6').forEach(function(p) {
                        if (!p.textContent.trim() && !p.querySelectorAll('img, iframe, video, audio, table').length) {
                            p.remove();
                        }
                    });

                    // Collapse multi-spaces within text nodes
                    var walker = document.createTreeWalker(tempDiv, NodeFilter.SHOW_TEXT, null, false);
                    var textNode;
                    while (textNode = walker.nextNode()) {
                        textNode.nodeValue = textNode.nodeValue.replace(/[ \t]{2,}/g, ' ');
                    }

                    var cleanedContent = tempDiv.innerHTML.trim();

                    if (typeof jQuery !== 'undefined' && jQuery('#wp-content-wrap').hasClass('html-active')) {
                        jQuery('#content').val(cleanedContent);
                    } else {
                        editor.setContent(cleanedContent);
                    }

                    if (editor.notificationManager) {
                        editor.notificationManager.open({
                            text: 'HTML & AI Whitespace Cleaned Successfully!',
                            type: 'success',
                            timeout: 2000
                        });
                    }
                } catch (e) {
                    console.error('Error in cleanhtml plugin:', e);
                    editor.windowManager.alert('An error occurred while cleaning HTML');
                }
            }
        });
    });
})();